<nav class="breadcrumbs"><a href="<?= e(url()) ?>">Ana sayfa</a><?php if(!empty($product['category_slug'])): ?> / <a href="<?= e(url('category/'.rawurlencode($product['category_slug']))) ?>"><?= e($product['category_name']) ?></a><?php endif; ?> / <?= e($product['name']) ?></nav><section class="product-detail"><div class="product-detail-image"><?php if($product['image']): ?><img src="<?= e($product['image']) ?>" alt="<?= e($product['name']) ?>"><?php else: ?><span>GAME</span><?php endif; ?></div><div class="product-detail-info"><p class="eyebrow">DİJİTAL OYUN ÜRÜNÜ</p><h1><?= e($product['name']) ?></h1><?php if(!empty($product['short_description'])): ?><p class="lead"><?= e($product['short_description']) ?></p><?php endif; ?><div class="detail-price" id="variantPrice"><?= number_format((float)$product['price'],2,',','.') ?> ₺</div><p class="delivery-note"><?= ($product['delivery_type']??'manual')==='automatic'?'Otomatik dijital teslimat':'Sipariş sonrası teslimat bilgisi' ?></p><form class="buy-form" method="post" action="<?= e(url('cart/add')) ?>"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="slug" value="<?= e($product['slug']) ?>"><?php if(!empty($productVariants)): ?><label>Ürün seçeneği <select name="variant_id" id="productVariant" required><option value="">Seçenek seçin</option><?php foreach($productVariants as $variant): ?><option value="<?= (int)$variant['id'] ?>" data-price="<?= e($variant['price']) ?>" data-stock="<?= (int)$variant['available_stock'] ?>"><?= e($variant['name']) ?><?= !empty($variant['sku'])?' · '.e($variant['sku']):'' ?> — <?= number_format((float)$variant['price'],2,',','.') ?> ₺</option><?php endforeach; ?></select></label><?php endif; ?><label>Adet <input type="number" name="quantity" min="1" max="20" value="1"></label><button type="submit" id="addToCartButton" <?= ($product['delivery_type']??'')==='automatic' && empty($productVariants) && (int)($available_stock??0)<1?'disabled':'' ?>>Sepete ekle</button></form><p class="stock-note" id="variantStockNote"><?= ($product['delivery_type']??'')==='automatic'?'Mevcut kod stoğu: '.(int)($available_stock??0):'Sipariş sonrası teslimat' ?></p></div></section><?php if(!empty($product['description'])): ?><section class="description-panel"><h2>Ürün açıklaması</h2><div><?= nl2br(e($product['description'])) ?></div></section><?php endif; ?><?php if($related): ?><section><h2>Benzer ürünler</h2><div class="products"><?php foreach($related as $p): ?><article class="product"><a class="product-link" href="<?= e(url('product/'.rawurlencode($p['slug']))) ?>"><div class="product-image"><?php if($p['image']): ?><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"><?php else: ?><span>GAME</span><?php endif; ?></div><h3><?= e($p['name']) ?></h3><p><?= e($p['short_description']) ?></p><strong><?= number_format((float)$p['price'],2,',','.') ?> ₺</strong></a></article><?php endforeach; ?></div></section><?php endif; ?><script>(()=>{const s=document.getElementById("productVariant"),p=document.getElementById("variantPrice"),b=document.getElementById("addToCartButton"),n=document.getElementById("variantStockNote");if(!s||!p)return;const automatic=<?= ($product['delivery_type']??'')==='automatic'?'true':'false' ?>;s.addEventListener("change",()=>{const o=s.options[s.selectedIndex];if(o&&o.dataset.price)p.textContent=Number(o.dataset.price).toLocaleString("tr-TR",{minimumFractionDigits:2,maximumFractionDigits:2})+" ₺";const stock=o?Number(o.dataset.stock||0):0;if(n&&automatic)n.textContent="Seçilen seçenek stok: "+stock;if(b&&automatic)b.disabled=!o||stock<1;});})();</script>